package com.fraud_rule_engine.rule;
import com.fraud_rule_engine.rule.engine.*; import com.fraud_rule_engine.rule.rules.*; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class RuleEngineCoreTests {
 private CompiledRule compile(String field,String op,Object value){return RuleCompiler.compile(RuleParser.standard().parse(Map.of("field",field,"op",op,"value",value)));}
 private EvalContext ctx(Object amount,String channel,boolean newDevice){return EvalContext.of(Map.of("amount",amount,"channel",channel,"newDevice",newDevice),Map.of());}
 @Test void everyRequiredOperatorWorks(){assertTrue(compile("amount","eq",10).matches(ctx(10,"POS",false)));assertTrue(compile("amount","ne",10).matches(ctx(11,"POS",false)));assertTrue(compile("amount","gt",9).matches(ctx(10,"POS",false)));assertTrue(compile("amount","gte",10).matches(ctx(10,"POS",false)));assertTrue(compile("amount","lt",11).matches(ctx(10,"POS",false)));assertTrue(compile("amount","lte",10).matches(ctx(10,"POS",false)));assertTrue(compile("channel","in",List.of("POS","ATM")).matches(ctx(10,"POS",false)));}
 @Test void nestedAllAnyNotWork(){Map<String,Object> tree=Map.of("all",List.of(Map.of("field","amount","op","gte","value",100),Map.of("any",List.of(Map.of("field","channel","op","eq","value","ECOM"),Map.of("not",Map.of("field","newDevice","op","eq","value",true))))));CompiledRule c=RuleCompiler.compile(RuleParser.standard().parse(tree));assertTrue(c.matches(ctx(120,"ECOM",false)));assertFalse(c.matches(ctx(120,"POS",true)));}
 @Test void blockOutranksReviewAndAllowIsDefault(){CompiledRule yes=compile("amount","gte",0);ActiveRule review=new ActiveRule(UUID.randomUUID(),"r",1,Action.REVIEW,1,Mode.ENFORCE,yes);ActiveRule block=new ActiveRule(UUID.randomUUID(),"b",1,Action.BLOCK,2,Mode.ENFORCE,yes);Evaluator e=new Evaluator();assertEquals(Verdict.BLOCK,e.evaluate(new RuleSet(4,List.of(review,block)),ctx(10,"POS",false)).verdict());assertEquals(Verdict.REVIEW,e.evaluate(new RuleSet(4,List.of(review)),ctx(10,"POS",false)).verdict());assertEquals(Verdict.ALLOW,e.evaluate(new RuleSet(4,List.of()),ctx(10,"POS",false)).verdict());}
 @Test void invalidLeafIncludesPath(){Map<String,Object> tree=Map.of("all",List.of(Map.of("field","unknownField","op","eq","value","x")));RuleValidationException ex=assertThrows(RuleValidationException.class,()->RuleParser.standard().parse(tree));assertTrue(ex.errors().get(0).contains("$.all[0].field"));}
 @Test void snapshotOnlyMovesForward(){SnapshotHolder h=new SnapshotHolder();assertTrue(h.swapIfNewer(new RuleSet(2,List.of())));assertFalse(h.swapIfNewer(new RuleSet(1,List.of())));}
}
